// Sound effects: plays public/sfx/<name>.mp3 when the file exists (generated by
// scripts/el-assets.mjs with ElevenLabs sound generation), else a tiny WebAudio blip so every cue
// still sounds. Nothing touches the DOM until the first play or preload.

export type SfxName = 'task-start' | 'task-done' | 'estop' | 'materialize' | 'blip' | 'reject' | 'talk-on' | 'talk-off';

export const SFX_NAMES: readonly SfxName[] = ['task-start', 'task-done', 'estop', 'materialize', 'blip', 'reject', 'talk-on', 'talk-off'];

type Note = { hz: number; endHz?: number; at: number; dur: number; type?: OscillatorType; level?: number };

/** Fallback synth recipes, one short phrase per cue. */
export const BLIPS: Record<SfxName, Note[]> = {
  blip: [{ hz: 1320, at: 0, dur: 0.05 }],
  'task-start': [
    { hz: 660, at: 0, dur: 0.07 },
    { hz: 990, at: 0.08, dur: 0.09 },
  ],
  'task-done': [
    { hz: 880, at: 0, dur: 0.08 },
    { hz: 1320, at: 0.09, dur: 0.16 },
  ],
  estop: [0, 0.18, 0.36, 0.54].map((at, i) => ({ hz: i % 2 ? 620 : 880, at, dur: 0.16, type: 'square' as const, level: 0.07 })),
  materialize: [{ hz: 300, endHz: 1400, at: 0, dur: 0.55, level: 0.08 }],
  reject: [
    { hz: 240, at: 0, dur: 0.1, type: 'square', level: 0.06 },
    { hz: 180, at: 0.12, dur: 0.14, type: 'square', level: 0.06 },
  ],
  'talk-on': [{ hz: 1200, at: 0, dur: 0.04 }],
  'talk-off': [{ hz: 800, at: 0, dur: 0.04 }],
};

let base = './sfx/';
let muted = false;
let volume = 0.5;
let ctx: AudioContext | null = null;
/** undefined = not probed yet, null = no file, element = file present */
const files = new Map<SfxName, HTMLAudioElement | null>();
const probes = new Map<SfxName, Promise<void>>();

export function setSfxMuted(m: boolean): void {
  muted = m;
}

export function setSfxVolume(v: number): void {
  volume = Math.max(0, Math.min(1, v));
}

export function setSfxBase(url: string): void {
  base = url.endsWith('/') ? url : `${url}/`;
  files.clear();
  probes.clear();
}

function probe(name: SfxName): Promise<void> {
  let p = probes.get(name);
  if (!p) {
    const url = `${base}${name}.mp3`;
    p = fetch(url, { method: 'HEAD' })
      .then((r) => {
        // A dev server answers a missing file with index.html: insist on an audio type.
        const ok = r.ok && /^audio\//.test(r.headers.get('content-type') ?? '');
        if (!ok) return void files.set(name, null);
        const a = new Audio(url);
        a.preload = 'auto';
        files.set(name, a);
      })
      .catch(() => void files.set(name, null));
    probes.set(name, p);
  }
  return p;
}

/** Check which generated files exist (call once, after the first click). */
export async function preloadSfx(): Promise<void> {
  await Promise.all(SFX_NAMES.map(probe));
}

export function playSfx(name: SfxName, gain = 1): void {
  if (muted || typeof window === 'undefined') return;
  const file = files.get(name);
  if (file) {
    const a = file.cloneNode() as HTMLAudioElement; // overlapping plays
    a.volume = Math.min(1, volume * gain);
    void a.play().catch(() => blip(name, gain));
    return;
  }
  blip(name, gain);
  if (file === undefined) void probe(name);
}

function blip(name: SfxName, gain: number): void {
  try {
    ctx ??= new AudioContext();
    if (ctx.state === 'suspended') void ctx.resume();
    const t0 = ctx.currentTime + 0.01;
    for (const n of BLIPS[name]) {
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.type = n.type ?? 'sine';
      osc.frequency.setValueAtTime(n.hz, t0 + n.at);
      if (n.endHz) osc.frequency.exponentialRampToValueAtTime(n.endHz, t0 + n.at + n.dur);
      const level = (n.level ?? 0.1) * volume * 2 * gain;
      g.gain.setValueAtTime(0.0001, t0 + n.at);
      g.gain.exponentialRampToValueAtTime(Math.max(0.0002, level), t0 + n.at + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + n.at + n.dur);
      osc.connect(g).connect(ctx.destination);
      osc.start(t0 + n.at);
      osc.stop(t0 + n.at + n.dur + 0.02);
    }
  } catch {
    // no audio available
  }
}

/** Seamless ambience loop (generated with loop: true). Call from a click. Returns stop(). */
export async function startAmbience(url = `${base}ambience.mp3`, level = 0.12): Promise<() => void> {
  const ac = new AudioContext();
  const res = await fetch(url);
  if (!res.ok || !/^audio\//.test(res.headers.get('content-type') ?? '')) {
    void ac.close();
    return () => {};
  }
  const buf = await ac.decodeAudioData(await res.arrayBuffer());
  const src = ac.createBufferSource();
  const g = ac.createGain();
  g.gain.value = level;
  src.buffer = buf;
  src.loop = true;
  // skip the MP3 encoder padding at both ends
  src.loopStart = 0.05;
  src.loopEnd = Math.max(0.1, buf.duration - 0.05);
  src.connect(g).connect(ac.destination);
  src.start(0, 0.05);
  return () => {
    try {
      src.stop();
    } catch {
      // already stopped
    }
    void ac.close();
  };
}
